<?php
$rootPrefix='../';$pageTitle='My account | Moleqra';require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/account_auth.php';$user=customer_user();if(!$user){header('Location: login.php');exit;}$pdo=db();$orders=[];if($pdo&&commerce_schema_ready($pdo)){$s=$pdo->prepare('SELECT order_number,order_token,status,payment_status,fulfilment_status,grand_total,currency,created_at FROM sales_orders WHERE customer_id=:id ORDER BY created_at DESC');$s->execute(['id'=>$user['id']]);$orders=$s->fetchAll();}require __DIR__.'/../includes/header.php';?>
<section class="page-hero"><div class="container"><div class="eyebrow">Customer account</div><h1>Hello, <?= e($user['first_name']) ?></h1><p><?= e($user['email']) ?></p></div></section><section class="section"><div class="container"><div class="admin-heading"><h2>Your orders</h2><form method="post" action="logout.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button class="btn" type="submit">Sign out</button></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Date</th><th>Payment</th><th>Fulfilment</th><th>Total</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><a href="../order.php?token=<?= e($o['order_token']) ?>"><?= e($o['order_number']) ?></a></td><td><?= e($o['created_at']) ?></td><td><?= e($o['payment_status']) ?></td><td><?= e($o['fulfilment_status']) ?></td><td><?= e($o['currency']) ?> <?= number_format((float)$o['grand_total'],2) ?></td></tr><?php endforeach;?><?php if(!$orders):?><tr><td colspan="5">No orders yet.</td></tr><?php endif;?></tbody></table></div></div></section><?php require __DIR__.'/../includes/footer.php';?>
